describe('observedEmbedProjectionToValue', () => {
  const value = {
    uid: 'value-uid',
    name: 'value-name',
    dashboard: { $ref: 'ref-dashboard' },
    panelUid: 'value-panelUid',
    origin: { $ref: 'ref-origin' },
    tokenHash: 'value-tokenHash',
    allowedOrigins: 'value-allowedOrigins',
    maxRange: 'value-maxRange',
    minRefresh: 'value-minRefresh',
    allowRaw: 'value-allowRaw',
    expiresAt: 'value-expiresAt',
    lastUsedAt: 'value-lastUsedAt',
    enabled: 'value-enabled',
    version: 'value-version',
  } as any;

  it('returns null without projection', () => {
    expect(observedEmbedProjectionToValue(null)).toBeNull();
    expect(observedEmbedProjectionToValue(undefined)).toBeNull();
  });

  it('keeps a plain value', () => {
    expect(observedEmbedProjectionToValue(value)).toEqual(value);
  });

  it('reduces the projected references to their key', () => {
    const projection = {
      uid: 'value-uid',
      name: 'value-name',
      dashboard: () => ({ uid: 'ref-dashboard' }),
      panelUid: 'value-panelUid',
      origin: () => ({ uid: 'ref-origin' }),
      tokenHash: 'value-tokenHash',
      allowedOrigins: 'value-allowedOrigins',
      maxRange: 'value-maxRange',
      minRefresh: 'value-minRefresh',
      allowRaw: 'value-allowRaw',
      expiresAt: 'value-expiresAt',
      lastUsedAt: 'value-lastUsedAt',
      enabled: 'value-enabled',
      version: 'value-version',
    } as any;
    expect(observedEmbedProjectionToValue(projection)).toEqual(value);
  });
});
